      SUBROUTINE DSEXT3CC     CALCULATES PARTIAL DERIVATIVES OF THIRD-ORDER MATRIX ELEMENTSC     WITH RESPECT TO THE MAGNETIC FIELD OF AN OCTUPOLEC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM6.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESC      REAL           DW2, S, W2C------------------------------------------------------------------------------      LINEAR = .FALSE.      W2 = 2.0*B/(RI*AP**2)      DW2 = 2.0*DPARM*UNITI(9)/(PREF*AP**2)      S = 2.0*W2*DW2*L**3/48.      UV(1,1) = S*L      UV(2,1) = 4.0*S      UV(3,10) = S*L      UV(4,10) = 4.0*S      S = 2.0*W2*DW2*L**4/48.      UV(1,2) = S*L      UV(2,2) = 5.0*S      UV(3,16) = S*L      UV(4,16) = 5.0*S      S = 2.0*W2*DW2*L**5/144.      UV(1,3) = S*L      UV(2,3) = 6.0*S      UV(3,19) = S*L      UV(4,19) = 6.0*S      S = 2.0*W2*DW2*L**6/1008.      UV(1,4) = S*L      UV(2,4) = 7.*S      UV(3,20) = S*L      UV(4,20) = 7.*S      S = 2.0*W2*DW2*L**3/48.      UV(1,8) = S*L      UV(2,8) = 4.0*S      UV(3,5) = S*L      UV(4,5) = 4.0*S      S = 0.05*W2*DW2*L**4      UV(1,14) = S*L      UV(2,14) = 5.0*S      UV(3,6) = S*L      UV(4,6) = 5.0*S      S = 2.0*W2*DW2*L**5/240.      UV(1,17) = S*L      UV(2,17) = 6.0*S      UV(3,7) = S*L      UV(4,7) = 6.0*S      S = - 2.0*W2*DW2*L**4/240.      UV(1,9) = S*L      UV(2,9) = 5.0*S      UV(3,11) = S*L      UV(4,11) = 5.0*S      S = 2.0*W2*DW2*L**5/360.      UV(1,15) = S*L      UV(2,15) = 6.0*S      UV(3,12) = S*L      UV(4,12) = 6.0*S      S = 2.0*W2*DW2*L**6/1008.      UV(1,18) = S*L      UV(2,18) = 7.0*S      UV(3,13) = S*L      UV(4,13) = 7.0*S      S = 0.25*DW2*L      UV(1,36) = S*L      UV(2,36) = 2.0*S      S = DW2*L**3/24.      UV(1,38) = S*L      UV(2,38) = 4.0*S      S = - 0.25*DW2*L      UV(1,41) = S*L      UV(2,41) = 2.0*S      S = - DW2*L**3/24.      UV(1,45) = S*L      UV(2,45) = 4.0*S      S = DW2*L**2/6.      UV(1,37) = S*L      UV(2,37) = 3.0*S      S = - DW2*L**2/6.      UV(1,44) = S*L      UV(2,44) = 3.0*S      S = - 0.5*DW2*L      UV(3,39) = S*L      UV(4,39) = 2.0*S      S = - DW2*L**2/6.      UV(3,40) = S*L      UV(3,42) = S*L      UV(4,40) = 3.0*S      UV(4,42) = 3.0*S      S = - DW2*L**3/6.      UV(3,43) = S*L      UV(4,43) = 4.0*S      RETURN      END